package com.learningspace;
import java.io.*;import java.nio.file.*;import org.json.*;
public class ShareDraftsCheck {
 public static void main(String[] args)throws Exception{if(!LocalImages.raster("data:image/png;base64,aGVsbG8=" )||!LocalImages.raster("data:image/jpeg;base64,aGVsbG8=")||LocalImages.raster("data:image/svg+xml;base64,aGVsbG8=")||LocalImages.raster("https://example.com/image.png")||LocalImages.raster("data:image/png;base64,<script>"))throw new Exception("Local image allowlist failed");File file=new File(Files.createTempDirectory("learning-shares-").toFile(),"pending.json");String text="A useful thread https://x.com/example/status/123";ShareDrafts.add(file,"share-one",text);ShareDrafts.add(file,"share-one",text);if(ShareDrafts.read(file).length()!=1)throw new Exception("Duplicate share");ShareDrafts.add(file,"share-two",new String(new char[20000]).replace('\0','a'));if(ShareDrafts.read(file).getJSONObject(1).getString("text").length()>10000)throw new Exception("Unbounded share");ShareDrafts.acknowledge(file,"share-one");if(ShareDrafts.read(file).length()!=1||!ShareDrafts.read(file).getJSONObject(0).getString("id").equals("share-two"))throw new Exception("Wrong acknowledgement");ShareDrafts.acknowledge(file,"share-two");if(ShareDrafts.read(file).length()!=0)throw new Exception("Queue not cleared");ShareDrafts.add(file,"share-one",text);ShareDrafts.add(file,"replayed-uuid",text);if(ShareDrafts.read(file).length()!=0)throw new Exception("A handled share came back");for(int i=0;i<20;i++)ShareDrafts.add(file,"share-"+i,text+" #"+i);boolean rejected=false;try{ShareDrafts.add(file,"too-many",text+" extra");}catch(IOException e){rejected=true;}if(!rejected||ShareDrafts.read(file).length()!=20)throw new Exception("Queue bound failed");file.delete();new File(file.getPath()+".handled").delete();file.getParentFile().delete();File imgs=new File(Files.createTempDirectory("learning-images-").toFile(),"pending.json");String a1="11111111-1111-1111-1111-111111111111.jpg",a2="22222222-2222-2222-2222-222222222222.jpg";
if(!ShareDrafts.add(imgs,"img-1","",a1,1000L))throw new Exception("Image-only share refused");
if(ShareDrafts.add(imgs,"img-dup","",a1,1000L))throw new Exception("Same image queued twice");
if(!ShareDrafts.add(imgs,"img-2","",a2,1000L))throw new Exception("A second screenshot was blocked by the first");
ShareDrafts.acknowledge(imgs,"img-1",2000L);
if(!ShareDrafts.add(imgs,"img-3","","33333333-3333-3333-3333-333333333333.jpg",3000L))throw new Exception("Acknowledging one screenshot blocked new ones");
if(ShareDrafts.add(imgs,"img-1","","44444444-4444-4444-4444-444444444444.jpg",3000L))throw new Exception("A handled share id came back");
if(!ShareDrafts.read(imgs).getJSONObject(0).optString("image").equals(a2))throw new Exception("Image name not kept");
boolean bad=false;try{ShareDrafts.add(imgs,"img-x","","../evil.jpg",3000L);}catch(IllegalArgumentException e){bad=true;}if(!bad)throw new Exception("Unsafe image name accepted");
imgs.delete();new File(imgs.getPath()+".handled").delete();imgs.getParentFile().delete();
System.out.println("Native incoming share checks passed: durable drafts, idempotency, text bounds, acknowledgement, no replay of handled shares, image drafts, capacity, and local raster image allowlist.");}
}
